/// Підставляє значення в шаблон з позиційними `{}` (порядок як у рядку перекладу).
pub fn fmt(tmpl: &str, args: &[&dyn std::fmt::Display]) -> String {
    let mut out = String::new();
    let mut rest = tmpl;
    let mut it = args.iter();
    while let Some(i) = rest.find("{}") {
        out.push_str(&rest[..i]);
        match it.next() {
            Some(a) => out.push_str(&a.to_string()),
            None => out.push_str("{}"),
        }
        rest = &rest[i + 2..];
    }
    out.push_str(rest);
    out
}

/// Рядок поточної мови за ключем (ключ або український текст). Невідомий ключ повертається як є.
pub fn tr(key: &'static str) -> &'static str {
    match TABLE.iter().find(|r| r.0 == key) {
        Some(r) => match lang() {
            Lang::Uk => r.1,
            Lang::En => r.2,
            Lang::Ru => r.3,
        },
        None => key,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_is_complete_and_unique() {
        for (i, r) in TABLE.iter().enumerate() {
            assert!(!r.1.is_empty() && !r.2.is_empty() && !r.3.is_empty(), "порожній переклад: {}", r.0);
            assert!(TABLE[..i].iter().all(|o| o.0 != r.0), "дубль ключа: {}", r.0);
        }
        set_lang(Lang::Uk);
        assert_eq!(tr("btn.cancel"), "Скасувати");
        assert_eq!(tr("no.such.key"), "no.such.key");
        set_lang(Lang::En);
        assert_eq!(tr("btn.cancel"), "Cancel");
        assert_eq!(tr("Немає токена"), "No token");
        set_lang(Lang::Ru);
        assert_eq!(tr("Немає токена"), "Нет токена");
        assert_eq!(fmt("Крок {} з 6", &[&3]), "Крок 3 з 6");
        set_lang(Lang::En);
        assert_eq!(fmt(tr("Крок {} з 6"), &[&3]), "Step 3 of 6");
        set_lang(Lang::Uk);
        set_lang(Lang::Uk);
    }
}
